using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using LogicLegends.Graph;
using UnityEditor;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveGraphChecks
    {
        [Serializable]sealed class CheckResult{public string name;public bool passed;}
        [Serializable]sealed class Report{public bool passed;public string scope="Native Editor Book/Hand/buttons, actual CharacterController route movement and authoritative shared deadline. Camera checks cover stable screen-space UI. Physical Android is separate.";public List<CheckResult> checks=new List<CheckResult>();public List<string> errors=new List<string>();}
        static Report report;static ArchiveTopicSession session;static ArchiveTopicStation station;static ArchiveGraphUI ui;static bool active,oldHunting;static double next;static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();
        public static string Status{get;private set;}="Idle";
        static ArchiveStationState State=>session.State.stations[8];
        static void Check(bool ok,string name){report.checks.Add(new CheckResult{name=name,passed=ok});if(!ok)throw new InvalidOperationException(name);}
        public static string ValidateVariants(){var c=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(ArchiveTopicSetup.Folder+"/Archive_Topic_Catalog.asset");var r=new Report();int variants=0;Action<bool,string> test=(ok,name)=>{r.checks.Add(new CheckResult{name=name,passed=ok});if(!ok)r.errors.Add(name);};
            try{test(c.graphs==AssetDatabase.LoadAssetAtPath<GraphChallengeCatalog>("Assets/Prefabs/Graph/GraphChallenges.asset"),"Same original fifty-variant solo graph catalog");for(int group=0;group<5;group++)for(int entry=0;entry<10;entry++){
                int round=group;var original=c.graphs.variantSets[group].variants[entry];int seed=Enumerable.Range(1,4096).First(n=>ReferenceEquals(ArchiveTopicQuestions.Build(c,8,round,n).graph,original));var q=ArchiveTopicQuestions.Build(c,8,group,seed);var good=ArchiveTopicChecks.Solution(q);string key="Challenge "+(group+1)+" / variant "+(entry+1);variants++;
                test(ReferenceEquals(q.graph,original)&&q.nodeIds.SequenceEqual(original.vertices.Select(v=>v.id)),key+" preserves source IDs, display labels, topology and lesson");test(ArchiveTopicQuestions.Validate(q,good,out _),key+" accepts the source answer");test(q.nodes.All(p=>Mathf.Abs(p.x)<=4.81f&&Mathf.Abs(p.y)<=4.81f),key+" fits the reserved arena");
                float ratio=-1;bool uniform=true;for(int i=1;i<q.nodes.Length;i++){float a=Vector3.Distance(original.vertices[0].position,original.vertices[i].position),b=Vector2.Distance(q.nodes[0],q.nodes[i]);if(a<.01f)continue;float current=b/a;if(ratio<0)ratio=current;else uniform&=Mathf.Abs(ratio-current)<.0001f;}test(uniform,key+" uniformly preserves the source geometry");
                var malformed=ArchiveTopicChecks.Solution(q);malformed.route.Add(999);test(!ArchiveTopicQuestions.Validate(q,malformed,out _),key+" rejects malformed route IDs");
                if(original.type==GraphChallengeType.Degree){var wrong=ArchiveTopicChecks.Solution(q);wrong.selection=(wrong.selection+1)%7;test(!ArchiveTopicQuestions.Validate(q,wrong,out _)&&good.selection>=0&&good.selection<=6,key+" supports the solo degree range 0 through 6");continue;}
                var walked=new ArchiveStationState();ArchiveTopicQuestions.Prepare(q,walked);double now=1;ArchiveGraphTraversal.Begin(walked,q,7,ArchiveGraphTraversal.Vertex(q,good.route[0]),now);
                for(int leg=1;leg<good.route.Count;leg++){var a=ArchiveGraphTraversal.Vertex(q,good.route[leg-1]);var b=ArchiveGraphTraversal.Vertex(q,good.route[leg]);int steps=Mathf.CeilToInt(Vector3.Distance(a,b)/.13f);for(int step=1;step<=steps;step++)ArchiveGraphTraversal.Sample(walked,q,Vector3.Lerp(a,b,step/(float)steps),now+=.03,.18f);}
                test(walked.continuous&&walked.routeAtVertex&&walked.route.SequenceEqual(good.route)&&ArchiveTopicQuestions.Validate(q,walked,out _),key+" records a complete physical route through connecting midpoints");
                var clone=JsonUtility.FromJson<ArchiveStationState>(JsonUtility.ToJson(walked));test(clone.routeAtVertex&&clone.route.SequenceEqual(walked.route)&&ArchiveTopicQuestions.Validate(q,clone,out _),key+" restores the route through a snapshot");clone.routeAtVertex=false;test(!ArchiveTopicQuestions.Validate(q,clone,out _),key+" cannot confirm from between vertices");
                var interrupted=new ArchiveStationState();ArchiveTopicQuestions.Prepare(q,interrupted);var start=ArchiveGraphTraversal.Vertex(q,good.route[0]);ArchiveGraphTraversal.Begin(interrupted,q,7,start,1);ArchiveGraphTraversal.Sample(interrupted,q,start+Vector3.up*3,1.1);test(!interrupted.continuous,key+" rejects unsupported height");ArchiveGraphTraversal.Begin(interrupted,q,7,start,1);ArchiveGraphTraversal.Sample(interrupted,q,ArchiveGraphTraversal.Vertex(q,good.route[1]),1.01,teleporting:true);test(!interrupted.continuous,key+" rejects teleporting between endpoints");
                if(original.type==GraphChallengeType.DirectedPath){var edge=original.edges.First(e=>e.directed);int end=Array.IndexOf(q.nodeIds,edge.destination),begin=Array.IndexOf(q.nodeIds,edge.source);var reverse=new ArchiveStationState{route=new List<int>{end},continuous=true,routeAtVertex=true,lastRoutePosition=ArchiveGraphTraversal.Vertex(q,end),routeSampleAt=1,routeSampleValid=true};var a=ArchiveGraphTraversal.Vertex(q,end);var b=ArchiveGraphTraversal.Vertex(q,begin);for(int step=1;step<=30;step++)ArchiveGraphTraversal.Sample(reverse,q,Vector3.Lerp(a,b,step/30f),1+step*.05);test(!reverse.continuous,key+" rejects reverse directed travel");}
                if(original.type==GraphChallengeType.Cycle){var repeat=ArchiveTopicChecks.Solution(q);repeat.route.Insert(2,repeat.route[0]);test(!ArchiveTopicQuestions.Validate(q,repeat,out _),key+" rejects repeated intermediate cycle vertices");}
            }}catch(Exception e){r.errors.Add(e.ToString());}r.passed=r.errors.Count==0&&r.checks.All(c=>c.passed);Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T9GraphVariants.json",JsonUtility.ToJson(r,true));return(r.passed?"Passed":"Failed")+": "+variants+" variants / "+r.checks.Count+" checks";
        }
        public static void Begin(){if(!Application.isPlaying||Photon.Pun.PhotonNetwork.InRoom||active)throw new InvalidOperationException("Use offline Play Mode.");session=ArchiveTopicSession.Current;station=session.stations[8];ui=ArchiveTopicUI.Current.GetComponent<ArchiveGraphUI>();report=new Report();oldHunting=session.hunting.enabled;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);session.hunting.enabled=false;stack.Clear();stack.Push(Flow());active=true;next=0;Status="Starting";EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}
        static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);}
        static void Tick(){if(!active)return;try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup<next)return;if(!Application.isPlaying)throw new Exception("Play stopped.");if(stack.Count==0){Finish(true);return;}var flow=stack.Peek();if(!flow.MoveNext()){stack.Pop();return;}if(flow.Current is IEnumerator nested)stack.Push(nested);else next=EditorApplication.timeSinceStartup+(flow.Current is float delay?delay:0);}catch(Exception ex){report.errors.Add(Status+": "+ex);Finish(false);}}
        static void Move(Vector3 p)=>ArchiveTopicPlayChecks.MoveTo(station,p);
        static IEnumerator Book(){Move(ArchiveTopicStation.BookPosition+Vector3.back*1.7f);station.points.First(p=>p.role==ArchivePointRole.Book).Interact();yield return .25f;ArchiveTopicUI.Current.Close();}
        static IEnumerator Claim(){var q=session.Question(8);Move(ArchiveGraphTraversal.Vertex(q,ArchiveGraphTraversal.StartIndex(q)));yield return .2f;station.points.First(p=>p.role==ArchivePointRole.Node&&p.index==ArchiveGraphTraversal.StartIndex(q)).Interact();yield return .15f;Check(State.routeActor==session.LocalActor&&State.continuous&&State.route.Count==1,"Hand claims exactly one route runner on the actual start rune");}
        static IEnumerator WalkLeg(int target){var q=session.Question(8);var p=ArchiveGraphTraversal.Vertex(q,target);var world=station.transform.TransformPoint(p);var cc=Player.LocalInstance.GetComponent<CharacterController>();int guard=0;while(true){var delta=world-Player.LocalInstance.transform.position;delta.y=0;if(delta.magnitude<.10f)break;if(guard++>300)throw new Exception("Physical route movement blocked.");cc.Move(delta.normalized*Mathf.Min(.22f,delta.magnitude));yield return .035f;}yield return .2f;Check(State.continuous&&State.routeAtVertex&&State.route.Last()==target,"Actual capsule movement records arrival at "+ArchiveGraphPresentation.Label(q,target));}
        static IEnumerator WalkAnswer(){var q=session.Question(8);var solution=ArchiveTopicChecks.Solution(q);yield return Claim();for(int i=1;i<solution.route.Count;i++)yield return WalkLeg(solution.route[i]);}
        static IEnumerator Flow(){session.Initialize(314159);ArchiveTopicUI.Current.Close();yield return .4f;Check(!State.timerRunning&&State.timerAttempt==0,"T9 clock waits for first Book activation");Status="T9 physical edge traversal and UI";yield return Book();Check(State.timerRunning&&State.timerLimit==600&&session.ActiveTopic==8&&session.graphIncorrectPenaltySeconds==10,"Book starts the shared ten-minute graph clock and reserves T9");var q=session.Question(8);double deadline=State.timerDeadline;ArchiveTopicUI.Current.Open(station);yield return .15f;Check(ui.IsOpen&&Time.timeScale==1&&session.CanAct(session.LocalActor)&&State.timerDeadline==deadline,"Reading graph map does not pause or lock the player");var map=ui.GetComponentInChildren<ArchiveGraphMapGraphic>();Check(map!=null&&map.GetComponent<CanvasRenderer>()!=null&&map.canvasRenderer.GetMesh()!=null&&map.canvasRenderer.GetMesh().vertexCount>0,"The live map renders a real edge/node UI mesh, not only labels");ArchiveTopicUI.Current.Close();Check(State.routeActor==0&&State.route.Count<=1,"Book activation does not silently claim a route");station.points.First(p=>p.role==ArchivePointRole.Node&&p.index!=ArchiveGraphTraversal.StartIndex(q)).Interact();Check(State.routeActor==0,"Interacting with a goal cannot fabricate traversal");ArchiveTopicUI.Current.Close();
            yield return Claim();var before=State.route.ToArray();Move(ArchiveGraphTraversal.Vertex(q,before[0])+new Vector3(0,0,2));yield return .25f;Check(!State.continuous&&State.route.SequenceEqual(before)&&session.State.mistakes.Count==0,"Off-path movement interrupts the route without inventing an answer mistake");session.Request(8,ArchiveAction.RetryRoute);Check(!State.continuous,"Retry is rejected away from the start");yield return WalkAnswer();ui.CheckButton.onClick.Invoke();yield return .25f;Check(State.round==1&&State.phase==0&&!State.timerRunning&&State.reveal.Contains("→"),"Confirm accepts walked edge and pauses remaining time at the next Book gate");float remaining=session.TimerRemaining(State);yield return .3f;Check(session.TimerRemaining(State)==remaining,"Solved Book gate freezes the same remaining clock");session.Request(0,ArchiveAction.Start);Check(session.ActiveTopic==8&&session.State.stations[0].timerAttempt==0,"Another topic cannot start while T9 is unfinished");
            Status="T9 degree choices, penalties and timeout";yield return Book();q=session.Question(8);Check(session.TimerRemaining(State)<=remaining&&session.TimerRemaining(State)>remaining-2,"Next Book resumes remaining time rather than refilling it");ArchiveTopicUI.Current.Open(station);yield return .15f;int correct=q.graph.Degree(q.graph.degreeVertex),wrong=(correct+1)%7;Check(ui.DegreeButtons.All(b=>b.gameObject.activeInHierarchy&&b.interactable),"All seven original degree choices are available");ui.DegreeButtons[wrong].onClick.Invoke();yield return .1f;deadline=State.timerDeadline;ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.selection==wrong&&session.State.mistakes.Count==1&&Math.Abs(State.timerDeadline-(deadline-10))<.000001,"Incorrect degree keeps choice and deducts exactly ten seconds and one actor mistake");ui.RetryButton.onClick.Invoke();Check(State.selection==-1&&State.timerDeadline==deadline-10,"Clear choice leaves timer and mistake history intact");ui.DegreeButtons[correct].onClick.Invoke();yield return .1f;int attempt=State.timerAttempt;State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .25f;Check(State.timerExpired&&State.round==1&&State.selection==correct&&session.State.mistakes.Count==2,"Timeout preserves solved challenge, degree choice and exactly one timeout mistake");ArchiveTopicUI.Current.Close();yield return Book();Check(State.selection==correct&&State.timerAttempt==attempt+1&&session.TimerRemaining(State)>598,"Timeout Book retry retains the current variant and choice");yield return 1.6f;session.Request(8,ArchiveAction.Submit);yield return .2f;Check(State.round==2&&State.phase==0,"Preserved degree answer completes challenge two");
            for(int round=2;round<5;round++){Status="T9 walking "+new[]{"edge","degree","simple path","directed path","cycle"}[round];yield return Book();q=session.Question(8);Check(q.graph.type==(GraphChallengeType)round,"T9 round "+(round+1)+" uses its original solo challenge type");yield return WalkAnswer();Check(ArchiveTopicQuestions.Validate(q,State,out _),"Physical route satisfies original "+q.graph.type+" validator");session.Request(8,ArchiveAction.Submit);yield return .25f;Check(State.round==round+1,"Room progresses after "+q.graph.type);}
            Check(State.phase==2&&State.round==5&&!State.timerRunning&&session.ActiveTopic==-1,"All five graph challenges finish and release the next topic");Check(session.State.stations.Where(s=>s.topic!=8).All(s=>s.round==0&&s.timerAttempt==0),"T9 leaves the other nine topic states and clocks unchanged");
            Status="T9 art and camera stability";var art=station.GetComponent<ArchiveGraphPresentation>();Check(art.VertexRoots.Length==q.nodes.Length&&art.PathRoots.Length==q.graph.edges.Count(e=>e.traversalEnabled),"Graph props match every original node and enabled edge");Check(art.VertexRoots.All(v=>v.Find("Vertex_Inlay").GetComponent<Renderer>().bounds.min.y>v.Find("Vertex_Stone").GetComponent<Renderer>().bounds.max.y),"Colored vertex inlays remain visible above their stone meshes");Check(art.arrivalSound!=null&&art.correctSound!=null&&art.incorrectSound!=null&&art.sparkMesh!=null&&art.sparkMaterial!=null,"Graph arrival and answer sound/mesh feedback assets are assigned");Check(art.GetComponentsInChildren<Collider>().Length==1,"New graph props add no collision or navigation blockers");Move(Vector3.zero);ArchiveTopicUI.Current.Close();yield return .2f;var position=ui.Objective.anchoredPosition;var size=ui.Objective.sizeDelta;var camera=Camera.main;var rotation=camera.transform.rotation;for(int i=0;i<12;i++){camera.transform.rotation=Quaternion.Euler(12+i*3,i*30,0);yield return .05f;Check(ui.IsObjectiveVisible&&ui.Objective.anchoredPosition==position&&ui.Objective.sizeDelta==size,"Compact graph UI stays fixed at camera angle "+i);}camera.transform.rotation=rotation;
        }
        static void Finish(bool ok){active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;stack.Clear();if(session!=null&&Application.isPlaying){session.hunting.enabled=oldHunting;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);ArchiveTopicUI.Current.Close();}report.passed=ok&&report.errors.Count==0&&report.checks.All(c=>c.passed);Status=report.passed?"Passed":"Failed";Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T9PolishPlayMode.json",JsonUtility.ToJson(report,true));Debug.Log("T9 Path of Connections: "+Status+" / "+report.checks.Count);}
    }
}
